package com.slotix.reservationcore.availability; import com.slotix.reservationcore.common.*; import com.slotix.reservationcore.resource.*; import org.springframework.http.*; import org.springframework.stereotype.*; import org.springframework.transaction.annotation.*; import org.springframework.web.server.*; import java.util.*;
@Service public class ResourceBlockService{final ResourceBlockRepository blocks;final ResourceRepository resources;final TenantAccessService access;public ResourceBlockService(ResourceBlockRepository b,ResourceRepository r,TenantAccessService a){blocks=b;resources=r;access=a;}@Transactional public ResourceBlockResponse create(UUID c,UUID r,CreateResourceBlockRequest q){access.requireActiveMembership(c);if(!q.endAt().isAfter(q.startAt()))throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,"The block interval is invalid");resources.findByIdAndCompanyIdAndDeletedAtIsNull(r,c).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Resource not found"));return ResourceBlockResponse.from(blocks.save(ResourceBlock.create(c,r,q.startAt(),q.endAt(),q.reason().trim(),q.blockType())));}@Transactional(readOnly=true) public List<ResourceBlockResponse> list(UUID c,UUID r){access.requireActiveMembership(c);return blocks.findByCompanyIdAndResourceIdAndDeletedAtIsNullOrderByStartAtAsc(c,r).stream().map(ResourceBlockResponse::from).toList();}}
